output_text:
[
  {
    "id": "no_hand_carrying",
    "text": "Customers are prohibited from carrying shopping items by hand; merchandise must be transported without making the handFull state true.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "must_take_cart_first",
    "text": "A shopper is obliged to take the cart from the cart station before proceeding with the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cart_station": "at(1,5)",
        "cart_waiting_at_station": "cartAt(1,5)"
      },
      "events": {
        "cart_acquired": {
          "pre": {
            "and": [
              "cart_station",
              "cart_waiting_at_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cart_acquired"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "Customers are prohibited from picking up shelf items unless they currently have a shopping cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        },
        "item_pickup_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "return_cart_after_collecting_items",
    "text": "After collecting any required item, the shopper is obliged to return the cart to the return bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "item_collected": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cart_returned_to_bay": {
          "pre": {
            "and": [
              "return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_collected",
      "discharge": "cart_returned_to_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from exiting the supermarket while still in possession of a cart.",
    "abstraction": {
      "state_properties": {
        "at_exit": "at(9,5)",
        "still_has_cart": "hasCart"
      },
      "events": {
        "exit_attempt_with_cart": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT",
              "still_has_cart"
            ]
          },
          "post": null
        },
        "exit_attempt_without_cart": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT",
              {
                "not": "still_has_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_attempt_with_cart"
    }
  },
  {
    "id": "no_carts_in_exit_corridor",
    "text": "Shopping carts are prohibited in the pedestrian exit corridor on the eastern side of the store.",
    "abstraction": {
      "state_properties": {
        "exit_corridor": {
          "or": [
            "at(7,2)",
            "at(7,3)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_corridor": {
          "and": [
            "hasCart",
            "exit_corridor"
          ]
        }
      },
      "events": {
        "enter_exit_corridor_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "exit_corridor"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_corridor"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A shopper may put down a cart only at the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "not_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "cart_left_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_return_bay"
            ]
          },
          "post": null
        },
        "cart_left_at_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "return_bay"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_left_outside_return_bay"
    }
  },
  {
    "id": "cart_narrow_shortcuts_forbidden",
    "text": "Carts are prohibited from taking the narrow eastbound shortcut movements from the lower aisle at (2,5) or from the egg aisle at (6,4).",
    "abstraction": {
      "state_properties": {
        "lower_shortcut_entry": "at(2,5)",
        "egg_aisle_east_entry": "at(6,4)",
        "cart_at_narrow_eastbound_entry": {
          "and": [
            "hasCart",
            {
              "or": [
                "lower_shortcut_entry",
                "egg_aisle_east_entry"
              ]
            }
          ]
        }
      },
      "events": {
        "cart_uses_lower_shortcut": {
          "pre": {
            "and": [
              "hasCart",
              "lower_shortcut_entry",
              "E"
            ]
          },
          "post": null
        },
        "cart_uses_egg_aisle_shortcut": {
          "pre": {
            "and": [
              "hasCart",
              "egg_aisle_east_entry",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_uses_lower_shortcut",
          "cart_uses_egg_aisle_shortcut"
        ]
      }
    }
  }
]
